<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { listManagedServers, type ManagedServer } from '../api/server-mgmt'
import { createInspection, deleteOpsDatabase, detectDatabaseLogs, diagnoseDatabase, getDatabaseEvent, getLogCursors, importOpsDatabase, listDatabaseEvents, listOpsDatabases, saveOpsDatabase, syncDatabaseLogs, type DatabaseActivity, type DatabaseDiagnostic, type DatabaseEvent, type OpsDatabase } from '../api/operations'
const router=useRouter(),databases=ref<OpsDatabase[]>([]),servers=ref<ManagedServer[]>([]),selected=ref<number>(),diagnostic=ref<DatabaseDiagnostic>(),diagnosing=ref(false),diagnosticError=ref(''),tab=ref('locks'),refreshSeconds=ref(0),lastRefresh=ref(0),editing=ref(false),saving=ref(false),detecting=ref(false)
const current=computed(()=>databases.value.find(d=>d.id===selected.value)),waiting=computed(()=>diagnostic.value?.activities.filter(a=>a.waitEventType==='Lock')||[]),slow=computed(()=>diagnostic.value?.activities.filter(a=>a.state==='active'&&a.elapsedSeconds>=5)||[])
const events=ref<DatabaseEvent[]>([]),total=ref(0),page=ref(1),keyword=ref(''),minimum=ref<number>(),range=ref<[Date,Date]|null>(null),eventLoading=ref(false),detail=ref<DatabaseEvent>(),detailVisible=ref(false),cursors=ref<any[]>([]),cursorVisible=ref(false)
const draft=reactive<Partial<OpsDatabase>>({}),capability=ref<Record<string,string>>()
const time=(v:string|null|undefined)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'-'
const seconds=(v:number)=>v<60?v.toFixed(1)+' 秒':v<3600?(v/60).toFixed(1)+' 分钟':(v/3600).toFixed(1)+' 小时'
const historyType=computed(()=>({deadlocks:'deadlock',history:'slow_sql',lockHistory:'lock_wait'}[tab.value]||''))
function rootBlockers(pid:number,path=new Set<number>()):string[]{if(path.has(pid))return [`${pid}（循环／快照待核实）`];const a=diagnostic.value?.activities.find(a=>a.pid===pid);if(!a)return [pid===0?'准备事务（PID 0）':`${pid}（会话详情未取得）`];if(!a.blockingPids?.length)return [String(pid)];const next=new Set(path).add(pid);return [...new Set(a.blockingPids.flatMap(p=>rootBlockers(p,next)))]}
function waitTime(a:DatabaseActivity){const locks=diagnostic.value?.locks.filter(l=>l.pid===a.pid&&!l.granted&&l.waitStart)||[];return locks.length?seconds(Math.max(...locks.map(l=>l.waitSeconds))):'未取得等待起点'}
async function reloadDatabases(){const rows=await listOpsDatabases();databases.value=rows;if(!selected.value&&rows.length)selected.value=rows[0]!.id}
async function refreshDiagnostic(){if(!selected.value||diagnosing.value)return;const id=selected.value;diagnosing.value=true;try{const value=await diagnoseDatabase(id);if(selected.value===id){diagnostic.value=value;diagnosticError.value=''}}catch(e:any){if(selected.value===id)diagnosticError.value=e.message}finally{diagnosing.value=false;lastRefresh.value=Date.now()}}
let eventRequest=0
async function loadEvents(){const token=++eventRequest,id=selected.value,type=historyType.value;if(!id||!type){eventLoading.value=false;return};eventLoading.value=true;try{const result=await listDatabaseEvents(id,{type,page:page.value,pageSize:30,keyword:keyword.value,minDuration:minimum.value,from:range.value?.[0].toISOString(),to:range.value?.[1].toISOString()});if(token===eventRequest){events.value=result.list;total.value=result.total}}finally{if(token===eventRequest)eventLoading.value=false}}
watch(selected,()=>{diagnostic.value=undefined;diagnosticError.value='';page.value=1;events.value=[];total.value=0;refreshDiagnostic();loadEvents()})
watch(tab,()=>{page.value=1;events.value=[];total.value=0;loadEvents()})
function edit(row?:OpsDatabase){Object.keys(draft).forEach(k=>delete (draft as any)[k]);Object.assign(draft,row?{...row,password:''}:{name:'',host:'',port:5432,database:'',username:'',password:'',sslMode:'require',serverId:0,logEnabled:false,logDirectory:'',logFormat:'csv',logTimezone:'Asia/Shanghai',slowThresholdMs:5000,lookbackHours:24});capability.value=undefined;editing.value=true}
async function save(){saving.value=true;try{const row=await saveOpsDatabase(draft);editing.value=false;await reloadDatabases();selected.value=row.id;ElMessage.success('实例与日志接入配置已保存')}finally{saving.value=false}}
async function importCurrent(){const row=await importOpsDatabase();await reloadDatabases();selected.value=row.id;ElMessage.success('已导入当前连接，日志采集默认关闭；可编辑为专用监控账号')}
async function detect(){if(!selected.value)return;detecting.value=true;try{const values=await detectDatabaseLogs(selected.value);edit(current.value);capability.value=values;draft.logDirectory=values.resolved_directory;draft.logFormat=values.format;draft.logTimezone=values.log_timezone||'Asia/Shanghai';draft.logPrefix=values.log_line_prefix;draft.slowThresholdMs=Number(values.log_min_duration_statement)>0?Number(values.log_min_duration_statement):5000;ElMessage.success('已检测，确认配置后保存即可接入日志')}finally{detecting.value=false}}
async function sync(){if(!selected.value)return;await syncDatabaseLogs(selected.value);ElMessage.success('后台日志同步已接受，可查看读取进度')}
async function showCursors(){if(!selected.value)return;cursors.value=await getLogCursors(selected.value);cursorVisible.value=true}
async function showEvent(row:DatabaseEvent){detail.value=await getDatabaseEvent(selected.value!,row.id);detailVisible.value=true}
async function inspect(){if(!selected.value)return;const run=await createInspection(`${current.value?.name} 数据库巡检`,[{type:'database',id:selected.value}]);router.push(`/inspections/${run.id}`)}
async function remove(){if(!selected.value)return;await ElMessageBox.confirm('删除数据库诊断连接？已有巡检报告和日志记录保留。','删除连接',{type:'warning'});await deleteOpsDatabase(selected.value);selected.value=undefined;diagnostic.value=undefined;await reloadDatabases()}
async function copy(text:string){try{if(navigator.clipboard)await navigator.clipboard.writeText(text);else{const e=document.createElement('textarea');e.value=text;document.body.append(e);e.select();document.execCommand('copy');e.remove()};ElMessage.success('已复制')}catch{ElMessage.error('复制失败，请手动选择文本')}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{servers.value=await listManagedServers();await reloadDatabases();timer=setInterval(()=>{if(refreshSeconds.value&&Date.now()-lastRefresh.value>=refreshSeconds.value*1000)refreshDiagnostic();if(historyType.value){reloadDatabases();loadEvents()}},10000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template><div class="database-diagnostics"><div class="heading"><div><h3>数据库诊断</h3><p>当前锁与 SQL 按需查询；历史慢 SQL 和死锁通过数据库日志增量接入</p></div><div class="actions"><el-button @click="importCurrent">导入当前 PostgreSQL 连接</el-button><el-button type="primary" @click="edit()">新增实例</el-button></div></div>
<div class="toolbar"><el-select v-model="selected" placeholder="选择数据库实例" style="width:320px"><el-option v-for="d in databases" :key="d.id" :label="`${d.name} · ${d.host}/${d.database}`" :value="d.id"/></el-select><template v-if="current"><el-button @click="edit(current)">编辑连接</el-button><el-button :loading="detecting" @click="detect">检测日志配置</el-button><el-button @click="inspect">发起巡检</el-button><el-button text type="danger" @click="remove">删除</el-button></template></div>
<el-empty v-if="!current" description="添加实例或导入当前 PostgreSQL 连接后开始诊断"/>
<template v-else><div class="snapshot-bar"><span>{{current.host}}:{{current.port}} / {{current.database}}</span><span>当前快照：{{time(diagnostic?.checkedAt)}}</span><el-select v-model="refreshSeconds" style="width:135px"><el-option label="手动刷新" :value="0"/><el-option label="每 10 秒" :value="10"/><el-option label="每 30 秒" :value="30"/><el-option label="每 60 秒" :value="60"/></el-select><el-button :loading="diagnosing" @click="refreshDiagnostic">刷新当前诊断</el-button></div>
<el-alert v-if="diagnosticError" :title="diagnosticError" type="error" :closable="false" show-icon/><el-alert v-for="w in diagnostic?.warnings" :key="w" :title="w" type="warning" :closable="false"/><el-alert v-if="diagnostic?.truncated" title="本次会话或锁明细达到上限，页面不是完整明细；请缩小范围或结合数据库工具核实" type="warning" :closable="false"/>
<div class="summary"><div><span>当前锁等待会话</span><strong>{{diagnostic?waiting.length:'-'}}</strong></div><div><span>当前运行 ≥5 秒 SQL</span><strong>{{diagnostic?slow.length:'-'}}</strong></div><div><span>当前库连接数</span><strong>{{diagnostic?.connections??'-'}}</strong></div><div><span>累计死锁次数</span><strong>{{diagnostic?.deadlocks??'-'}}</strong><small>自统计重置 {{time(diagnostic?.statsReset)}}</small></div></div>
<el-tabs v-model="tab" class="tabs"><el-tab-pane label="锁与锁等待" name="locks"><el-table :data="waiting" size="small" row-key="pid" empty-text="本次快照未取得锁等待会话，请同时核对采集权限"><el-table-column type="expand"><template #default="{row}"><div class="sql-detail"><p>根阻塞源：{{rootBlockers(row.pid).join('、')}}</p><pre>{{row.query}}</pre></div></template></el-table-column><el-table-column prop="pid" label="等待 PID" width="95"/><el-table-column label="直接阻塞者" width="135"><template #default="{row}">{{row.blockingPids.join('、')||'-'}}</template></el-table-column><el-table-column label="根阻塞源" min-width="150"><template #default="{row}">{{rootBlockers(row.pid).join('、')}}</template></el-table-column><el-table-column label="锁等待时长" min-width="130"><template #default="{row}">{{waitTime(row)}}</template></el-table-column><el-table-column prop="username" label="账号" width="125"/><el-table-column prop="client" label="客户端" width="145"/><el-table-column prop="waitEvent" label="等待事件" width="130"/><el-table-column prop="query" label="SQL" min-width="240" show-overflow-tooltip/></el-table>
<h4>相关锁对象</h4><el-table :data="diagnostic?.locks||[]" size="small"><el-table-column prop="pid" label="PID" width="90"/><el-table-column prop="lockType" label="类型" width="140"/><el-table-column prop="mode" label="锁模式" width="200"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.granted?'success':'warning'" size="small">{{row.granted?'已持有':'等待中'}}</el-tag></template></el-table-column><el-table-column prop="object" label="对象／事务"/></el-table>
<h4>相关会话及长事务</h4><el-table :data="diagnostic?.activities||[]" size="small"><el-table-column type="expand"><template #default="{row}"><div class="sql-detail"><p>事务开始 {{time(row.transactionStart)}} · SQL 开始 {{time(row.queryStart)}}</p><pre>{{row.query}}</pre><el-button size="small" @click="copy(row.query)">复制 SQL</el-button></div></template></el-table-column><el-table-column prop="pid" label="PID" width="90"/><el-table-column prop="username" label="账号" width="130"/><el-table-column prop="state" label="会话状态" width="165"/><el-table-column label="事务时长" width="120"><template #default="{row}">{{row.transactionStart?seconds(row.transactionSeconds):'-'}}</template></el-table-column><el-table-column prop="query" label="SQL（非活跃会话为最后一条）" show-overflow-tooltip/></el-table></el-tab-pane>
<el-tab-pane label="当前长时间运行 SQL" name="live"><el-alert title="仅展示当前 active 且运行达到 5 秒的 SQL，时长包含锁等待；结束后的历史明细请查看慢 SQL 日志。SQL 文本受数据库 track_activity_query_size 限制。" type="info" :closable="false"/><el-table :data="slow" size="small"><el-table-column type="expand"><template #default="{row}"><div class="sql-detail"><pre>{{row.query}}</pre><el-button size="small" @click="copy(row.query)">复制 SQL</el-button></div></template></el-table-column><el-table-column prop="pid" label="PID" width="95"/><el-table-column label="已运行" width="120"><template #default="{row}">{{seconds(row.elapsedSeconds)}}</template></el-table-column><el-table-column prop="username" label="账号" width="130"/><el-table-column prop="waitEventType" label="等待类型" width="120"/><el-table-column prop="waitEvent" label="等待事件" width="130"/><el-table-column prop="query" label="SQL" min-width="300" show-overflow-tooltip/></el-table></el-tab-pane>
<el-tab-pane label="死锁日志" name="deadlocks"/><el-tab-pane label="历史慢 SQL 日志" name="history"/><el-tab-pane label="历史锁等待日志" name="lockHistory"/>
</el-tabs>
<template v-if="historyType"><div class="log-status"><div><el-tag :type="current.logEnabled?'success':'info'">{{current.logEnabled?'后台增量接入':'日志接入未启用'}}</el-tag><span>最近同步尝试：{{time(current.lastLogSyncAt)}}</span><span>首次导入起点：{{time(current.logStartAt)}}</span></div><div><el-button size="small" @click="showCursors">读取进度</el-button><el-button size="small" @click="sync">立即同步</el-button></div></div>
<el-alert v-if="current.logError" type="error" :title="current.logError" :closable="false"/>
<el-alert v-if="!current.logEnabled" title="日志尚未启用接入，空列表不能代表没有历史事件。点击“检测日志配置”，确认日志所在主机、目录及格式后保存并启用。" type="warning" :closable="false"/>
<div class="event-filters"><el-input v-model="keyword" placeholder="SQL、账号、数据库或错误关键词" clearable style="width:260px" @keyup.enter="page=1;loadEvents()"/><el-date-picker v-model="range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间" style="width:360px"/><el-input-number v-if="tab==='history'" v-model="minimum" :min="0" placeholder="最小耗时 ms" :controls="false" style="width:130px"/><el-button @click="page=1;loadEvents()">查询日志</el-button></div>
<p class="muted">{{tab==='history'?`展示已采集、达到 ${current.slowThresholdMs} ms 阈值的日志记录；Parse／Bind／Execute 阶段分别保留，日志条数不等同于全部 SQL 执行次数。`:tab==='deadlocks'?'死锁详情来自 PostgreSQL 原始日志；累计计数与历史日志明细属于不同数据来源。':'需要数据库已开启 log_lock_waits；未开启或日志字段缺失时不能恢复未记录的等待历史。'}}</p>
<el-table :data="events" v-loading="eventLoading" size="small" @row-dblclick="showEvent"><el-table-column label="发生时间" width="175"><template #default="{row}">{{time(row.eventTime)}}</template></el-table-column><el-table-column prop="dbName" label="数据库" width="110"/><el-table-column prop="username" label="账号" width="110"/><el-table-column prop="pid" label="PID" width="80"/><el-table-column v-if="tab==='history'" label="耗时" width="100"><template #default="{row}">{{(row.durationMs/1000).toFixed(3)}} 秒</template></el-table-column><el-table-column v-if="tab==='history'" prop="phase" label="阶段" width="90"/><el-table-column prop="sql" label="SQL" min-width="250" show-overflow-tooltip/><el-table-column prop="message" label="日志消息" min-width="190" show-overflow-tooltip/><el-table-column width="75"><template #default="{row}"><el-button text type="primary" @click="showEvent(row)">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="30" :total="total" layout="total,prev,pager,next" @current-change="loadEvents"/>
</template></template>
<el-dialog v-model="editing" :title="draft.id?'编辑数据库连接与日志接入':'新增数据库实例'" width="760px"><el-form label-width="120px"><div class="form-grid"><el-form-item label="名称"><el-input v-model="draft.name"/></el-form-item><el-form-item label="数据库地址"><el-input v-model="draft.host"/></el-form-item><el-form-item label="端口"><el-input-number v-model="draft.port" :min="1" :max="65535"/></el-form-item><el-form-item label="数据库"><el-input v-model="draft.database"/></el-form-item><el-form-item label="账号"><el-input v-model="draft.username"/></el-form-item><el-form-item label="密码"><el-input v-model="draft.password" type="password" show-password autocomplete="new-password" :placeholder="draft.id?'留空保留现有密码':''"/></el-form-item><el-form-item label="SSL 模式"><el-select v-model="draft.sslMode"><el-option v-for="s in ['require','verify-ca','verify-full','disable']" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="日志／执行主机"><el-select v-model="draft.serverId" clearable placeholder="选择数据库日志所在主机"><el-option v-for="s in servers" :key="s.id" :label="`${s.remark||s.host} · ${s.host}`" :value="s.id"/></el-select></el-form-item></div><el-divider>日志接入：沿用数据库现有记录配置</el-divider><el-form-item label="日志目录"><el-input v-model="draft.logDirectory" placeholder="服务器上的绝对路径，如 /opt/PostgreSQL/14/data/log"/></el-form-item><div class="form-grid"><el-form-item label="日志格式"><el-select v-model="draft.logFormat"><el-option value="csv" label="PostgreSQL CSV"/><el-option value="text" label="文本日志"/></el-select></el-form-item><el-form-item label="日志时区"><el-input v-model="draft.logTimezone"/></el-form-item><el-form-item label="采集阈值 ms"><el-input-number v-model="draft.slowThresholdMs" :min="1" :max="3600000"/></el-form-item><el-form-item label="首次回溯小时"><el-input-number v-model="draft.lookbackHours" :min="1" :max="720"/></el-form-item><el-form-item label="启用日志接入"><el-switch v-model="draft.logEnabled"/></el-form-item></div><p class="muted">采集阈值是平台的日志筛选条件，不会修改 PostgreSQL 配置。后台约每 30 秒读取新增日志，事件保留 30 天。修改首次回溯范围不会重置已经保存的读取位置。</p><el-alert v-if="capability" :title="`检测结果：logging_collector=${capability.logging_collector}，log_destination=${capability.log_destination}，慢日志阈值=${capability.log_min_duration_statement} ms，log_lock_waits=${capability.log_lock_waits}`" type="info" :closable="false"/></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></template></el-dialog>
<el-dialog v-model="detailVisible" title="日志记录详情" width="85%"><template v-if="detail"><el-descriptions :column="3" border size="small"><el-descriptions-item label="时间">{{time(detail.eventTime)}}</el-descriptions-item><el-descriptions-item label="数据库">{{detail.dbName||'日志未记录'}}</el-descriptions-item><el-descriptions-item label="账号">{{detail.username||'日志未记录'}}</el-descriptions-item><el-descriptions-item label="PID">{{detail.pid||'-'}}</el-descriptions-item><el-descriptions-item label="SQLSTATE">{{detail.sqlState||'-'}}</el-descriptions-item><el-descriptions-item label="阶段／耗时">{{detail.phase}} {{detail.durationMs}} ms</el-descriptions-item><el-descriptions-item label="应用">{{detail.application||'日志未记录'}}</el-descriptions-item><el-descriptions-item label="客户端">{{detail.client||'日志未记录'}}</el-descriptions-item><el-descriptions-item label="原始偏移">{{detail.sourceOffset}}</el-descriptions-item></el-descriptions><h4>SQL <el-button size="small" text @click="copy(detail.sql)">复制</el-button></h4><pre>{{detail.sql||'日志没有提供可关联的 SQL 文本'}}</pre><template v-for="field in ['message','detail','hint','context'] as const" :key="field"><h4 v-if="detail[field]">{{field.toUpperCase()}}</h4><pre v-if="detail[field]">{{detail[field]}}</pre></template><h4>原始日志 · {{detail.sourcePath}}</h4><pre>{{detail.raw}}</pre></template></el-dialog>
<el-dialog v-model="cursorVisible" title="日志读取进度" width="900px"><el-table :data="cursors" size="small"><el-table-column prop="path" label="日志文件" min-width="300"/><el-table-column label="已读／文件字节" width="180"><template #default="{row}">{{row.offset}} / {{row.lastSize}}</template></el-table-column><el-table-column prop="lastError" label="读取错误" show-overflow-tooltip/><el-table-column label="更新时间" width="170"><template #default="{row}">{{time(row.updatedAt)}}</template></el-table-column></el-table><p class="muted">读取位置按文件身份保存。轮转、截断会重新识别；跨批次不完整的记录保留到下次读取。</p></el-dialog>
</div></template>
<style scoped>.database-diagnostics{display:flex;flex-direction:column;gap:16px;padding-bottom:24px}.heading,.actions,.toolbar,.snapshot-bar,.log-status,.log-status>div,.event-filters{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.heading,.log-status{justify-content:space-between}.heading h3{margin:0}.heading p,.muted{font-size:12px;color:#78899c;line-height:1.8}.heading p{margin-bottom:0}.toolbar,.snapshot-bar,.tabs,.log-status,.event-filters{background:#fff;padding:14px 16px;border:1px solid #e2e8f0;border-radius:6px}.snapshot-bar{font-size:12px;color:#65758b}.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.summary>div{background:#fff;border:1px solid #e2e8f0;border-radius:7px;padding:16px}.summary span,.summary small{font-size:11px;color:#78899c;display:block}.summary strong{display:block;font-size:28px;color:#243e60;margin:10px 0}.summary small{line-height:1.7}.tabs h4{margin:24px 0 12px;font-size:13px}.sql-detail{padding:10px 24px}.sql-detail p{font-size:12px;color:#66788c}pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;background:#f6f8fb;padding:12px;border:1px solid #e2e8f0;border-radius:4px;max-height:420px;overflow:auto;font-size:12px;line-height:1.7}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}.form-grid :deep(.el-select){width:100%}.log-status{font-size:12px;color:#65758b}.el-pagination{justify-content:flex-end}@media(max-width:1100px){.summary{grid-template-columns:repeat(2,1fr)}.form-grid{grid-template-columns:1fr}}</style>
